"""Migrated Meridian CRM 4.2 opportunity_pipeline workflow."""

from typing import Any


def _amount_is_positive(record: dict) -> bool:
    """Evaluate legacy VRL: NVL(AMT,0) > 0."""
    value = record.get("AMT", "")
    if value is None or value == "":
        value = 0

    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def _has_close_date(record: dict) -> bool:
    """Evaluate legacy VRL: CLOSE_DT <> '00000000'."""
    return record.get("CLOSE_DT", "") != "00000000"


def _has_lost_reason(record: dict) -> bool:
    """Evaluate legacy VRL: LOST_RSN <> ''."""
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity pipeline transition."""
    result_record = dict(record)

    transitions = (
        ("P", "Q", "qualify", _amount_is_positive, (
            ("set", "STAGE_PCT", "25"),
            ("audit", "OPP_QUAL"),
        )),
        ("Q", "N", "advance", None, (
            ("set", "STAGE_PCT", "60"),
        )),
        ("N", "W", "close_won", _has_close_date, (
            ("set", "STAGE_PCT", "100"),
            ("audit", "OPP_WON"),
            ("notify", "won_deal"),
        )),
        ("P", "L", "close_lost", _has_lost_reason, (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        )),
        ("Q", "L", "close_lost", _has_lost_reason, (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        )),
        ("N", "L", "close_lost", _has_lost_reason, (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        )),
    )

    for from_state, to_state, transition_event, guard, actions in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        audits: list[str] = []
        notifies: list[str] = []

        for action in actions:
            kind = action[0]
            if kind == "set":
                result_record[action[1]] = action[2]
            elif kind == "audit":
                audits.append(action[1])
            elif kind == "notify":
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
